  /* ═════════════════ CORAL MACTRA — catálogo "Tudo sobre Coral Mactra" (5 pilares) ═════════════════ */
  add({ id: 'mactra_mactraset_1000', imagem: 'assets/produtos/coral_mactraset.jpg', fornecedor: 'linha_coral_mactra_impermeabilizantes', marca: 'Coral Mactra', nome: 'Mactraset 1.000', linha: 'Impermeabilizar', classe: 'impermeabilizante_fundacao', superficies: ['fundação/alicerce', 'umidade em rodapé', 'banheiros térreos', 'cozinhas térreas', 'paredes externas sem incidência solar'], acabamento: ['não aplicável'], diluicao: 'Bicomponente: acrescentar o componente B (pó) aos poucos no componente A (líquido branco "leitinho") e misturar; sempre umedecer a superfície', demaos: 'Em média 3 demãos cruzadas', rend_tipo: 'consumo', rend: { '9 kg': 4.5, '18 kg': 9 }, obs: 'Rígido. Indicado somente para área térrea. Rendimento para alicerces: até 4,5 m² (9 kg) e até 9 m² (18 kg). Componente A: 1 ou 2 unidades de 2 L; componente B Tradicional: pó cinza (1 ou 2 unidades de 7 kg); componente B Branco: pó branco para áreas que receberão mármores e granitos, só na caixa de 18 kg. Ferramentas: broxa, trincha de nylon ou vassoura de pelo. Mix essencial. Vende junto: Mactracol e Mactra 2.000. Similares: Vedacit Vedatop Bicomponente; Quartzolit Tecplus Top; Viapol Viaplus Top e Viaplus 1.000; Sika Sikatop 100; Bautech Bautech 1.000; Dryko Drykotec 1.100; Denver Denvertec 100.', destaque: 'Produto "coringa" fracionado na proporção ideal, que corrige e previne infiltração e umidade em áreas protegidas do sol em todo o ciclo da obra.' });
  add({ id: 'mactra_mactraset_flex_5000', imagem: 'assets/produtos/coral_mactraset.jpg', fornecedor: 'linha_coral_mactra_impermeabilizantes', marca: 'Coral Mactra', nome: 'Mactraset Flexível 5.000', linha: 'Impermeabilizar', classe: 'manta_liquida', superficies: ['banheiros', 'cozinhas', 'áreas molháveis', 'piscinas e reservatórios (com Vedatrinca Tela)'], acabamento: ['não aplicável'], diluicao: 'Bicomponente: acrescentar o componente B (pó cinza) aos poucos no componente A ("leitinho") e misturar; sempre umedecer', demaos: 'De 3 a 4 demãos cruzadas', rend_tipo: 'consumo', rend: { '18 kg': 5 }, obs: 'Rendimento até 5 m² final por caixa de 18 kg (2 x 2 L de componente A + 2 x 7 kg de componente B). Precisa ser aplicado com a Vedatrinca Tela. Não altera a potabilidade da água (em tanques de piscicultura, conferir o pH antes de colocar os peixes). Maior rentabilidade que o Mactraset 1.000. Antigo Vedbem Piscina. Mix essencial. Vende junto: Vedatrinca Tela 1 m x 50 m, Mactracol, Mactra 2.000 e Elastique PU 40. Similares: Vedacit Vedatop Flex Bicomponente; Quartzolit Tecplus Flex; Viapol Viaplus 5.000; Sika Sikatop Flex; Bautech Bautech 5.000; Dryko Drykotec 5.500; Denver Denvertec 540 Flex.', destaque: 'Corrige e previne infiltração e umidade em áreas molháveis como cozinhas e banheiros, com maior rentabilidade que o Mactraset 1.000.' });
  add({ id: 'mactra_mactraset_flex_fibras_7000', imagem: 'assets/produtos/coral_mactraset.jpg', fornecedor: 'linha_coral_mactra_impermeabilizantes', marca: 'Coral Mactra', nome: 'Mactraset Flexível Fibras 7.000', linha: 'Impermeabilizar', classe: 'manta_liquida', superficies: ['piscinas enterradas ou elevadas', 'reservatórios de água potável enterrados ou elevados', 'tanques de piscicultura', 'áreas molhadas e molháveis'], acabamento: ['não aplicável'], diluicao: 'Bicomponente: acrescentar o componente B (pó cinza) aos poucos no componente A ("leitinho") e misturar; sempre umedecer', demaos: 'De 4 a 5 demãos cruzadas', rend_tipo: 'consumo', rend: { '18 kg': 4 }, obs: 'Rendimento até 4 m² final por caixa de 18 kg (2 x 2 L de componente A + 2 x 7 kg de componente B). Dispensa a Vedatrinca Tela, exceto em ralos, cantos, trincas e juntas de concretagem. Não altera a potabilidade da água (em piscicultura, conferir o pH antes de colocar os peixes). Antigo Vedbem Fibras. Mix essencial. Vende junto: Mactracol, Mactra 2.000, Vedatrinca Tela 1 m x 50 m e Elastique PU 40. Similares: Vedacit Vedatop Flex Fibras Bicomponente; Quartzolit Tecplus Lastic; Viapol Viaplus 7.000; Sika SikaTop Flex Fibras; Bautech Bautech 7.000; Dryko Drykotec 7.700; Denver Denvertec 540 Fibras.', destaque: 'O maior ticket médio e rentabilidade da família Mactraset, para piscinas e reservatórios, dispensando a tela na maior parte da área.' });
  add({ id: 'mactra_betol', fornecedor: 'linha_coral_mactra_impermeabilizantes', marca: 'Coral Mactra', nome: 'Betol', linha: 'Impermeabilizar', classe: 'impermeabilizante_fundacao', superficies: ['fundações/alicerce', 'baldrame', 'mourão', 'muros de arrimo', 'vaso de planta de concreto ou cerâmica', 'primer para mantas asfálticas e fita asfáltica'], acabamento: ['não aplicável'], diluicao: 'Pronto para uso', demaos: '3 demãos', rend_tipo: 'consumo', rend: { '18 L': 45 }, obs: 'Líquido viscoso preto, à base de água. 18 L equivale a 45 até 90 m² final. Embalagens: 900 mL, 3,6 L e 18 L (balde) e 200 L (tambor). Ferramentas: pincel, trincha ou vassoura de pelo. Mix essencial. Vende junto: Fita Multiuso. Similares: Vedacit Neutrol à base de água; Quartzolit Pintura asfáltica Acqua; Viapol Viabit Acqua e Ecoprimer; Sika Igol Ecoasfalto e Igol 2; Dryko Drykoprimer Acqua; Denver Denver Manta Primer Acqua; Bautech não tem.', destaque: 'Primeira opção de impermeabilizante para fundação e alicerce: produto coringa, à base de água, de alto giro, econômico e de fácil aplicação.' });
  add({ id: 'mactra_vedbem_imperall', imagem: 'assets/produtos/coral_vedbem_imperall.jpg', fornecedor: 'linha_coral_mactra_impermeabilizantes', marca: 'Coral Mactra', nome: 'Vedbem Imperall', linha: 'Impermeabilizar', classe: 'impermeabilizante_parede', ambiente: 'exterior', superficies: ['paredes externas', 'fachadas externas'], acabamento: ['não aplicável'], diluicao: 'Primeira demão com até 20% de água limpa; demais demãos puras', demaos: '3 demãos', rend_tipo: 'consumo', rend: { '18 kg': 30 }, obs: 'Rendimento do 18 kg: de 30 até 75 m² final. Embalagens: 3,6 kg (balde e lata) e 18 kg (lata). Disponível em 20 cores do leque Coral. Antes de qualquer pintura aplicar o fundo preparador da Coral; pode receber pintura posterior, exceto pintura impermeabilizante. Ferramentas: broxa, pincel, trincha de nylon ou rolo de lã. Na tabela Paredes Exteriores: durabilidade boa, antimofo ótima, chuva boa, sol boa, rendimento ótimo. Antigo Imperall Premium 10 em 1. Mix essencial. Similares: Vedacit Vedapren Parede; Quartzolit Parede Premium Quartzolit; Sika Igolflex Fachada; Dryko Drykofachada; Bautech Bautech Imperparede; Viapol e Denver não têm.', destaque: 'Excelente custo-benefício: impermeabiliza, é hidrorrepelente e antimofo, em 20 cores do leque Coral.' });
  add({ id: 'mactra_vedbem_parede', imagem: 'assets/produtos/coral_vedbem_parede.jpg', fornecedor: 'linha_coral_mactra_impermeabilizantes', marca: 'Coral Mactra', nome: 'Vedbem Parede', linha: 'Impermeabilizar', classe: 'impermeabilizante_parede', ambiente: 'exterior', superficies: ['paredes externas', 'fachadas externas', 'selador impermeável para tinta acrílica', 'superfícies porosas'], acabamento: ['não aplicável'], diluicao: 'Primeira demão com até 10% de água limpa; demais demãos puras', demaos: 'Não informado no catálogo', rend_tipo: 'consumo', rend: { '18 kg': 30 }, obs: 'Rendimento do 18 kg: de 30 até 75 m² final. Embalagens: balde 3,6 kg (somente branco) e balde 18 kg (5 cores prontas: Branco, Areia do Saara, Camurça dos Andes, Concreto Urbano, Marrom Shitake). Antes de qualquer pintura aplicar o fundo preparador da Coral. Ideal para galpões, barracões e imóveis alugados. Ferramentas: pincel, trincha ou rolo de lã. Na tabela Paredes Exteriores: durabilidade média, antimofo ótima, chuva média, sol média, rendimento bom. Similares: Quartzolit Impermeabilizante Parede Quartzolit; Viapol Fuseprotec Parede; Bautech Bautech Parede; Vedacit, Sika, Dryko e Denver não têm.', destaque: 'Produto econômico, de baixo desembolso, que impermeabiliza, tem poder antimofo e é excelente selador acrílico para superfícies porosas.' });
  add({ id: 'mactra_acquafort', fornecedor: 'linha_coral_mactra_impermeabilizantes', marca: 'Coral Mactra', nome: 'Acquafort', linha: 'Impermeabilizar', classe: 'impermeabilizante_parede', ambiente: 'exterior', superficies: ['tijolo à vista', 'concreto aparente', 'pedras naturais', 'cerâmicas em geral'], acabamento: ['não aplicável'], diluicao: 'Pronto para uso', demaos: 'Apenas 1 demão bem carregada', rend_tipo: 'demao', rend: { '18 L': 36 }, obs: 'Hidrorrepelente com acabamento incolor. 18 L rende de 36 até 144 m² (uma demão). Embalagens: 3,6 L e 18 L (balde). Ferramentas: rolo, pincel, trincha de nylon, rolo de lã, rolo de espuma ou pulverizador de baixa pressão. Mix essencial. Similares: Vedacit Acquella Base Água; Quartzolit Repele Água 40W; Viapol Fuseprotec Hidro; Sika Silicone W; Bautech Protege Fachada; Denver Denver Repele Acqua; Dryko não tem.', destaque: 'Hidrorrepelente incolor que mantém a aparência natural da superfície, com o maior ticket médio e rentabilidade.' });
  add({ id: 'mactra_vedbem_manta_rapida', imagem: 'assets/produtos/coral_vedbem_manta.jpg', fornecedor: 'linha_coral_mactra_impermeabilizantes', marca: 'Coral Mactra', nome: 'Vedbem Manta Líquida Rápida', linha: 'Impermeabilizar', classe: 'manta_liquida', ambiente: 'exterior', superficies: ['lajes sem trânsito', 'marquises', 'áreas externas'], acabamento: ['não aplicável'], diluicao: 'Primeira demão 1:1 (uma parte de produto e uma de água limpa); demais demãos puras', demaos: 'De 3 a 4 demãos', rend_tipo: 'consumo', rend: { '18 kg': 15 }, obs: 'Pasta cremosa branca. 18 kg rende até 15 m². Embalagens: 5 kg e 18 kg (balde). Secagem rápida, com menor tempo de liberação da obra; resistente a intempéries. Ferramentas: pincel, broxa, trincha de nylon, vassoura de pelo macio ou rolo de lã. Antiga Manta Líquida Premium. Mix essencial. Vende junto: Vedatrinca Tela 25 cm x 5 m. Similares: Vedacit Vedapren Fast; Quartzolit Super Manta Líquida; Viapol Vedalage Plus; Sika Sikafill Rápido; Bautech Manta Líquida; Dryko Drykolaje Top; Denver Denvercril Super.', destaque: 'Excelente custo-benefício com secagem rápida: forma uma membrana que previne e combate infiltrações em lajes sem trânsito.' });
  add({ id: 'mactra_vedbem_manta_branca', imagem: 'assets/produtos/coral_vedbem_manta.jpg', fornecedor: 'linha_coral_mactra_impermeabilizantes', marca: 'Coral Mactra', nome: 'Vedbem Manta Líquida Branca', linha: 'Impermeabilizar', classe: 'manta_liquida', ambiente: 'exterior', superficies: ['lajes sem trânsito planas e inclinadas', 'marquises', 'jardineiras', 'calhas', 'rufos'], acabamento: ['não aplicável'], diluicao: 'Primeira demão com 50% de água limpa; demais demãos puras', demaos: '6 demãos', rend_tipo: 'consumo', rend: { '18 kg': 7.5 }, obs: 'Pasta cremosa branca. 18 kg rende até 7,5 m². Embalagens: 1 kg, 4,5 kg e 18 kg (balde). Membrana sem emendas, dispensa maçarico; pode ficar exposta a intempéries; aceita proteção mecânica para posterior revestimento cerâmico; excelente para manutenções industriais. Ferramentas: pincel, broxa, trincha de nylon ou vassoura de pelo. Antiga Manta Líquida Vedatrinca. Vende junto: Vedatrinca Tela 1 m x 50 m e Elastique PU 40. Similares: Vedacit Vedapren Branco; Quartzolit Manta Líquida Branca; Viapol Vedalage Branco; Sika Igolflex Rápido Branco; Dryko, Bautech e Denver não têm.', destaque: 'Produto de menor desembolso que forma membrana sem emendas, dispensa maçarico e aceita proteção mecânica para revestimento cerâmico.' });
  add({ id: 'mactra_vedbem_telhafria', fornecedor: 'linha_coral_mactra_impermeabilizantes', marca: 'Coral Mactra', nome: 'Vedbem Telhafria', linha: 'Impermeabilizar', classe: 'manta_liquida', ambiente: 'exterior', superficies: ['telhas de fibrocimento', 'telhas galvanizadas', 'telhas cerâmicas não esmaltadas', 'telhas de cimento e concreto tipo "canaletão"', 'silos de armazenagem'], acabamento: ['não aplicável'], diluicao: 'Primeira demão com até 20% de água limpa; demais demãos puras', demaos: '4 demãos', rend_tipo: 'consumo', rend: { '18 kg': 30 }, obs: 'Rendimento de 30 a 40 m² final (balde de 18 kg). Microesferas cerâmicas: impermeabiliza e dá conforto térmico, diminuindo o consumo de energia; evita mofo e aumenta a durabilidade das telhas. Ferramentas: broxa, pincel, trincha de nylon, rolo de lã ou airless. Antigo Telhafria. Mix essencial. Vende junto: Antiferrugem (o catálogo sugere oferecer o Antiferrugem com o Telhafria). Similares: Quartzolit Manta Líquida 7 e Manta Líquida Ultra 12; Bautech Bautech Gelado; Denver Denversol top reflective; Vedacit, Viapol, Sika e Dryko não têm.', destaque: 'Impermeabiliza e proporciona maior conforto térmico com microesferas cerâmicas, com o maior ticket médio e rentabilidade.' });
  add({ id: 'mactra_vedbem_telhado', fornecedor: 'linha_coral_mactra_impermeabilizantes', marca: 'Coral Mactra', nome: 'Vedbem Telhado', linha: 'Impermeabilizar', classe: 'manta_liquida', ambiente: 'exterior', superficies: ['telhas de amianto ou fibrocimento', 'telhas de cimento e concreto tipo "canaletão"'], acabamento: ['não aplicável'], diluicao: 'Primeira demão com até 20% de água limpa; demais demãos puras', demaos: '3 demãos', rend_tipo: 'consumo', rend: { '18 kg': 34 }, obs: '18 kg rende de 34 a 40 m² final. Embalagens: 3,6 kg e 18 kg (balde). Impermeabilizante (sem a função de conforto térmico do Telhafria); evita mofo na telha. Ferramentas: pincel, trincha de nylon, rolo de lã, vassoura de pelo ou airless. Antigo Vedatelha Vedaparede. Vende junto: telhas. Similares: Quartzolit Manta Telhado Brasilit; demais marcas não têm.', destaque: 'Dá acabamento e impermeabiliza telhas com excelente custo-benefício, com oportunidade de venda junto com as telhas.' });
  add({ id: 'mactra_vedmur', fornecedor: 'linha_coral_mactra_impermeabilizantes', marca: 'Coral Mactra', nome: 'Vedmur', linha: 'Impermeabilizar', classe: 'fundo_preparador', ambiente: 'ambos', superficies: ['rebocos', 'paredes externas', 'paredes internas', 'rodapés', 'selador de superfícies'], acabamento: ['não aplicável'], diluicao: 'Pronto para uso', demaos: '1 demão (2 demãos em superfície extremamente porosa)', rend_tipo: 'demao', rend: { '900 mL': 1.8, '5 L': 10 }, obs: 'Rendimento de 2 a 6 m²/L (valores por embalagem calculados pelo mínimo de 2 m²/L). Líquido branco leitoso. Multifunção: impermeabilizante e fundo preparador, com poder antimofo; prepara a parede para massa corrida e pintura. Embalagens: 900 mL (garrafa) e 5 L (galão). Ferramentas: pincel, broxa e rolo de lã ou espuma. Mix essencial. Similares: Sika Impermur; demais marcas não têm.', destaque: 'Impermeabilizante e fundo preparador em uma só demão, que aumenta a vida útil da massa corrida e da tinta, com alto ticket médio.' });
  add({ id: 'mactra_mactra_2000', fornecedor: 'linha_coral_mactra_impermeabilizantes', marca: 'Coral Mactra', nome: 'Mactra 2.000', linha: 'Aditivar', classe: 'aditivo_argamassa', superficies: ['alicerces', 'rebocos', 'revestimentos', 'pisos em contato com o solo', 'argamassa e concreto'], acabamento: ['não aplicável'], diluicao: 'Diluir na água de amassamento: 2 L/50 kg de cimento para reboco e 500 mL/50 kg de cimento para concreto', demaos: 'Não se aplica (aditivo)', rend_tipo: 'consumo', rend: { '18 L': 72 }, obs: 'Rendimento aproximado do 18 L: 72 a 100 m² por cm de espessura de argamassa impermeável. Líquido azul; aditivo impermeabilizante. Indicado para reboco com areia média; permite pintura sobre o reboco. Embalagens: 1 L (garrafa), 5 L (galão), 18 L (caixa com 9 sachês de 2 L) e 200 L (tambor). Ferramentas: colher de pedreiro; desempenar com desempenadeira de madeira. Mix essencial. Vende junto: Mactracol e Mactraset. Similares: Vedacit Vedacit Aditivo Impermeabilizante; Quartzolit Tecplus 1; Viapol Contra Umidade; Sika Sika 1; Bautech Bautech 1; Dryko Drykoveda; Denver Denverimper 1.', destaque: 'Produto coringa de alto giro da cesta básica do pedreiro: impermeabiliza o reboco, deixa a massa mais leve e evita umidade em paredes e rodapés.' });
  add({ id: 'mactra_ligmassa', fornecedor: 'linha_coral_mactra_impermeabilizantes', marca: 'Coral Mactra', nome: 'Ligmassa', linha: 'Aditivar', classe: 'aditivo_argamassa', superficies: ['argamassa de assentamento', 'argamassa de reboco'], acabamento: ['não aplicável'], diluicao: 'Diluir na água de amassamento: 50 a 100 mL/25 kg de cimento', demaos: 'Não se aplica (aditivo)', rend_tipo: 'consumo', obs: 'Rendimento do 18 L: de 180 a 360 porções (sem valor em m²). Líquido castanho escuro; aditivo plastificante para reboco com areia média. Embalagens: 900 mL (garrafa), 3,6 L (balde), 5 L (galão), 9 L (caixa com 180 sachês de 50 mL), 18 L (balde) e 200 L (tambor). Ferramentas: colher de pedreiro. Mix essencial. Vende junto: Mactracol. Similares: Vedacit Vedalit e Alvenarit; Quartzolit Adesivo Plastificante; Viapol Viacal; Sika Sikanol Alvenaria; Bautech Plast C; Dryko Drykal; Denver Denvercal.', destaque: 'Dá maior plasticidade ao reboco, evitando microfissuras, e deixa a massa mais leve e cremosa.' });
  add({ id: 'mactra_mactracol', fornecedor: 'linha_coral_mactra_impermeabilizantes', marca: 'Coral Mactra', nome: 'Mactracol', linha: 'Aditivar', classe: 'aditivo_argamassa', superficies: ['chapiscos', 'estucagem', 'recomposição de pisos', 'gesso em geral'], acabamento: ['não aplicável'], diluicao: '1:2 (uma parte de Mactracol para duas partes de água limpa) para chapiscos', demaos: 'Não se aplica (aditivo)', rend_tipo: 'consumo', rend: { '18 L': 60 }, obs: 'Rendimento médio do 18 L: 60 m². Líquido branco; aditivo colante. Embalagens: 900 mL, 3,6 L e 18 L (balde), 18 L (caixa com 9 sachês de 2 L) e 200 L (tambor). Ferramentas: colher de pedreiro. Cesta básica do pedreiro e do gesseiro. Mix essencial. Vende junto: Mactraset, Ligmassa ou Mactra 2.000. Similares: Vedacit Bianco; Quartzolit Chapix Blanco; Viapol Viafix; Sika Sika Chapisco Plus; Bautech Bautech Chapisco; Dryko Drykofix Chapisco; Denver Denverfix Chapisco.', destaque: 'Facilita o chapisco garantindo aderência rápida, com menor desembolso e qualidade e rendimento similares ao principal concorrente.' });
  add({ id: 'mactra_fixmassa', fornecedor: 'linha_coral_mactra_impermeabilizantes', marca: 'Coral Mactra', nome: 'Fixmassa', linha: 'Aditivar', classe: 'aditivo_argamassa', superficies: ['argamassa de assentamento', 'argamassa de reboco com areia fina ou média', 'argamassa de regularização de pisos', 'argamassa de enchimento'], acabamento: ['não aplicável'], diluicao: 'Diluir na água de amassamento: consumo de 500 mL/25 kg de cimento', demaos: 'Não se aplica (aditivo)', rend_tipo: 'consumo', obs: 'Consumo de 500 mL/25 kg de cimento (sem rendimento em m²). Líquido bege; aditivo fixante. Elimina o chapisco para reboco em superfícies porosas. Único aditivo que permite uso em areia fina, sem fissuras de retração ("pés de galinha"). Embalagem: garrafa de 500 mL. Similares: o catálogo diz que não possui concorrentes.', destaque: 'Elimina a necessidade de chapisco em superfícies porosas, gerando economia de tempo e dinheiro num serviço mais limpo e rápido.' });
  add({ id: 'mactra_megablock', fornecedor: 'linha_coral_mactra_impermeabilizantes', marca: 'Coral Mactra', nome: 'Megablock', linha: 'Aditivar', classe: 'aditivo_argamassa', superficies: ['blocos de concreto', 'pisos intertravados', 'peças pré-moldadas com pouca água (massa seca)', 'tubos de concreto'], acabamento: ['não aplicável'], diluicao: 'Diluir junto com parte da água de amassamento: 10 mL/kg de cimento', demaos: 'Não se aplica (aditivo)', rend_tipo: 'consumo', obs: 'Rendimento: 200 L para 500 sacos de 40 kg de cimento (sem valor em m²). Líquido viscoso azul; aditivo incorporador de ar e plastificante, adicionado no concreto. Evita perdas, retração e trincas e diminui a permeabilidade da argamassa. Embalagem: tambor de 200 L. Ideal para pequenas fábricas de pré-moldados e obras públicas. Similares: nenhuma das marcas listadas tem.', destaque: 'A solução correta de aditivo para concreto no lugar do detergente, de alta rentabilidade.' });
  add({ id: 'mactra_spray_secaparede', imagem: 'assets/produtos/coral_secaparede.jpg', fornecedor: 'linha_coral_mactra_impermeabilizantes', marca: 'Coral Mactra', nome: 'Spray Secaparede', linha: 'Bloquear Umidade', classe: 'umidade_rodape', ambiente: 'interior', superficies: ['rebocos com baixa resistência', 'reboco com pintura danificada', 'umidade de rodapé'], acabamento: ['não aplicável'], diluicao: 'Pronto para uso', demaos: 'De 1 a 2 demãos', rend_tipo: 'consumo', rend: { '750 mL': 2 }, obs: 'Rende de 2 a 4 m² por spray de 750 mL. Líquido branco leitoso, antimofo. Sistema Secaparede: 1º Spray (prepara a parede e bloqueia a umidade), 2º Massa Secaparede. Reparo paliativo para umidade ascendente, sem quebrar a parede. Mix essencial. Vende junto: Massa Secaparede. Similares: nenhuma das marcas listadas tem.', destaque: 'Reparo rápido e sem sujeira para umidade ascendente, sem quebrar a parede, de alta rentabilidade.' });
  add({ id: 'mactra_massa_secaparede', imagem: 'assets/produtos/coral_secaparede.jpg', fornecedor: 'linha_coral_mactra_impermeabilizantes', marca: 'Coral Mactra', nome: 'Massa Secaparede', linha: 'Bloquear Umidade', classe: 'umidade_rodape', ambiente: 'interior', superficies: ['paredes com umidade de rodapé'], acabamento: ['não aplicável'], diluicao: 'Pronta para uso', demaos: 'De 1 a 2 camadas de no máximo 2 mm', rend_tipo: 'consumo', rend: { '18 kg': 9 }, obs: 'Rende até 9 m² por balde de 18 kg. Pasta bege/rosada. Sistema Secaparede: 2º passo, depois do Spray; recupera a parede com umidade e dá acabamento. Ferramentas: espátula e desempenadeira de aço. Expor perto da massa corrida. Mix essencial. Vende junto: Spray Secaparede. Similares: Vedacit Vedatop Rodapé; Quartzolit Recupera Rodapé; Viapol Viaplus Reparo; Sika Monotop 123 Rodapé; Bautech Bautech Rodapé; Denver Denver Reparo; Dryko não tem.', destaque: 'Recupera paredes com umidade de rodapé de forma rápida, sem quebrar a parede, com fácil aplicação para pintores, pedreiros e consumidores.' });
  add({ id: 'mactra_vedatrinca_fita', imagem: 'assets/produtos/coral_vedatrinca.jpg', fornecedor: 'linha_coral_mactra_impermeabilizantes', marca: 'Coral Mactra', nome: 'Vedatrinca Fita', linha: 'Colar e Vedar', classe: 'fissura', superficies: ['trincas e fissuras pequenas (superficiais) em reboco', 'trincas e fissuras pequenas em gesso'], acabamento: ['não aplicável'], diluicao: 'Pronta para uso', demaos: 'Não se aplica', rend_tipo: 'consumo', obs: 'Fita branca. Tamanhos: 3 m x 5 cm (pacote), 5 m x 5 cm e 10 m x 5 cm (rolo). Sem rendimento informado. Ferramentas: tesoura, pincel, celuloide e espátula. No quadro da família: trincas pequenas = Vedatrinca Fita + massa acrílica + tinta. Antiga Fita Vedatrinca. Cesta básica do pedreiro e do pintor. Vende junto: massa acrílica e tinta. Similares: nenhuma das marcas listadas tem.', destaque: 'Solução rápida, prática e sem sujeira para trincas pequenas, de baixo custo e fácil venda complementar.' });
  add({ id: 'mactra_vedatrinca_selante', imagem: 'assets/produtos/coral_vedatrinca.jpg', fornecedor: 'linha_coral_mactra_impermeabilizantes', marca: 'Coral Mactra', nome: 'Vedatrinca Selante', linha: 'Colar e Vedar', classe: 'fissura', superficies: ['trincas e fissuras médias não estruturais'], acabamento: ['não aplicável'], diluicao: 'Primeira demão diluída em água 1:1; após 3 horas aplicar o produto puro', demaos: '1ª demão diluída + demão pura', rend_tipo: 'consumo', obs: 'Rendimento aproximado de 30 g por metro linear em juntas de 5 x 10 mm (sem valor em m²). Pasta viscosa bege; dispensa o uso de tela em pequenos reparos. Tamanhos: 280 g, 1,2 kg, 4,5 kg e 24 kg (balde). Ferramentas: espátula, desempenadeira e celuloide. Antigo Vedbem Trinca. Mix essencial. Similares: Sika Sikacryl 203; Viapol Hey\'dicryl Mástique; demais marcas não têm.', destaque: 'Solução rápida e fácil para trincas médias, sem quebrar a parede e sem precisar de tela.' });
  add({ id: 'mactra_vedatrinca_massa', imagem: 'assets/produtos/coral_vedatrinca.jpg', fornecedor: 'linha_coral_mactra_impermeabilizantes', marca: 'Coral Mactra', nome: 'Vedatrinca Massa', linha: 'Colar e Vedar', classe: 'fissura', superficies: ['trincas grandes (mais profundas) estabilizadas em alvenaria', 'preenchimento de buracos em alvenaria'], acabamento: ['não aplicável'], diluicao: 'Pronta para uso', demaos: 'Não informado no catálogo', rend_tipo: 'consumo', obs: 'Massa branca. Tamanhos: 1,2 kg e 25 kg (balde). Rendimento: não se aplica. Aceita pintura desde que se use o fundo preparador antes. Antiga Massa Vedatrinca. Vende junto: Vedatrinca Tela 10 cm x 3 m (com bandagem). Similares: Dryko Dryko Massa Acrílica Vedatudo; demais marcas não têm.', destaque: 'Solução para trincas grandes, com embalagem pequena para o consumidor final e grande para obras maiores.' });
  add({ id: 'mactra_vedatrinca_tela', imagem: 'assets/produtos/coral_vedatrinca.jpg', fornecedor: 'linha_coral_mactra_impermeabilizantes', marca: 'Coral Mactra', nome: 'Vedatrinca Tela', linha: 'Colar e Vedar', classe: 'fissura', superficies: ['reforço de impermeabilização em lajes sem trânsito', 'cozinhas', 'banheiros', 'piscinas e reservatórios', 'trincas grandes (mais profundas)'], acabamento: ['não aplicável'], diluicao: 'Pronta para uso; colocar após a primeira demão ou camada', demaos: 'Não se aplica', rend_tipo: 'consumo', obs: 'Tela de poliéster branca. Tamanhos: 10 cm x 3 m (pacote com bandagem, para trincas com Vedatrinca Massa), 25 cm x 5 m e 1 m x 50 m (rolos sem bandagem, para reforço de impermeabilização). Sem rendimento informado. Ferramentas: tesoura ou estilete. Antiga Tela Vedatrinca. Vende junto: Vedatrinca Massa, Mactraset Flexível 5.000, Mactraset Flexível Fibras 7.000, Vedbem Manta Líquida Rápida e Vedbem Manta Líquida Branca. Similares: Vedacit Vedacit Tela de Poliéster; Quartzolit Tela Estruturante Quartzolit; Viapol Mantex; Sika Sika Tela; Bautech Tela de Reforço; Dryko Drykotela; Denver Denvertela Poliéster.', destaque: 'Traz mais segurança ao reparo de fissuras e à impermeabilização, com baixo custo e fácil venda complementar.' });
  add({ id: 'mactra_compoxi_adesivo_mf', fornecedor: 'linha_coral_mactra_impermeabilizantes', marca: 'Coral Mactra', nome: 'Compóxi Adesivo MF', linha: 'Colar e Vedar', classe: 'adesivo_selante', superficies: ['concreto', 'cerâmicas', 'metais', 'pedras', 'madeira', 'chumbamento de pia e azulejos', 'pastilhas de piscina (sem esvaziar)'], acabamento: ['não aplicável'], diluicao: 'Bicomponente: misturar A (bege) e B (preto) separadamente, depois adicionar o B no A e misturar', demaos: 'Não se aplica', rend_tipo: 'consumo', obs: 'Consumo aproximado de 1,5 kg/m²/mm de espessura (sem rendimento por embalagem). Embalagem: 1 kg (A+B). Colagem estrutural; não se mistura em água. Ferramentas: pincel, trincha ou espátula. Mix essencial. Similares: Vedacit Compound Adesivo; Quartzolit Tecbond MF; Viapol Viapoxi Adesivo; Sika Sikadur Epóxi; Bautech EP Normal; Dryko Drykopoxi; Denver Denverpoxi.', destaque: 'Solução versátil para colagem estrutural, opção competitiva ao adesivo epóxi e excelente para venda complementar.' });
  add({ id: 'mactra_elastique_pu40', fornecedor: 'linha_coral_mactra_impermeabilizantes', marca: 'Coral Mactra', nome: 'Elastique PU 40', linha: 'Colar e Vedar', classe: 'adesivo_selante', superficies: ['juntas flexíveis', 'juntas de piso', 'mármores', 'tubulações e dutos', 'áreas molháveis/úmidas'], acabamento: ['não aplicável'], diluicao: 'Pronto para uso', demaos: 'Não se aplica', rend_tipo: 'consumo', obs: 'Rendimento aproximado de 3 m lineares em juntas de 1 x 1 cm por cartucho de 400 g. Pasta cinza, selante e elástica para colagem não estrutural; alta resistência a chuva e sol; aceita pintura. Ferramentas: estilete, pistola aplicadora e espátula. Similares: Vedacit Selante PU40; Quartzolit Selante PU40; Viapol Viapolsela PU40; Sika Sikaflex Universal; Bautech PU1 Turbo; Dryko Dryko Selante PU40 Flex Vedatudo; Denver não tem.', destaque: 'Produto coringa de alto giro para vedação e colagem não estrutural, inclusive em áreas molháveis, que aceita pintura.' });
  add({ id: 'mactra_spumix', fornecedor: 'linha_coral_mactra_impermeabilizantes', marca: 'Coral Mactra', nome: 'Spumix', linha: 'Colar e Vedar', classe: 'adesivo_selante', superficies: ['dutos e aparelhos de ar-condicionado', 'batentes de portas e janelas', 'isolamento térmico e acústico'], acabamento: ['não aplicável'], diluicao: 'Pronto para uso', demaos: 'Não se aplica', rend_tipo: 'consumo', obs: 'Rendimento de 3 a 4 L por 100 g (spray de 500 mL/340 g). Espuma expansiva branco-amarelada para preenchimento e fixação; secagem rápida, fácil de cortar. Cesta básica do pedreiro, eletricista e instaladores de ar-condicionado, portas e janelas. Similares: Vedacit Espuma Expansiva PU; Quartzolit Espuma Expansiva; Viapol Viapolsela Espuma; Sika Sika Boom M; Bautech Espuma PU; Dryko Dryko Selante Vedatudo Espuma Expansiva; Denver não tem.', destaque: 'Espuma expansiva versátil e de alto giro, com alto poder de expansão e isolamento térmico e acústico.' });
  add({ id: 'mactra_mcol_cola_branca', fornecedor: 'linha_coral_mactra_impermeabilizantes', marca: 'Coral Mactra', nome: 'Mcol Cola Branca', linha: 'Colar e Vedar', classe: 'adesivo_selante', superficies: ['madeiras de média e baixa densidade', 'laminados', 'papel', 'papelão', 'superfícies porosas'], acabamento: ['não aplicável'], diluicao: 'Pronta para uso', demaos: 'Não se aplica', rend_tipo: 'consumo', obs: 'Líquido viscoso branco fosco, à base de água; efeito transparente após a secagem; colagem a frio e a quente. Embalagens: 500 g e 1 kg. Rendimento: não se aplica. Similares: Vedacit Cola Branca PVA; Quartzolit Cola Branca PVA; demais marcas não têm.', destaque: 'Cola branca de alto desempenho, com alto poder de colagem e flexibilidade e efeito transparente após secar.' });
